package com.landportal.controller; import com.landportal.entity.*; import com.landportal.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/parcels") public class ParcelController{final ParcelRepository p;final OwnershipRepository o;final UserRepository u;public ParcelController(ParcelRepository p,OwnershipRepository o,UserRepository u){this.p=p;this.o=o;this.u=u;}@GetMapping public List<Parcel> mine(Authentication a){var user=u.findByEmail(a.getName()).orElseThrow();return o.findByUserId(user.getId()).stream().map(Ownership::getParcel).toList();}@GetMapping("/{id}") public Parcel one(@PathVariable Long id,Authentication a){var user=u.findByEmail(a.getName()).orElseThrow();if(user.getRole()!=Role.ADMIN&&!o.existsByUserIdAndParcelId(user.getId(),id))throw new RuntimeException("Access denied");return p.findById(id).orElseThrow();}}
